DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='sales_amount_nonnegative') THEN ALTER TABLE public.sales ADD CONSTRAINT sales_amount_nonnegative CHECK (amount IS NULL OR amount >= 0); END IF; IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='sales_currency_iso3') THEN ALTER TABLE public.sales ADD CONSTRAINT sales_currency_iso3 CHECK (currency IS NULL OR currency ~ '^[A-Z]{3}$'); END IF; IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='gateway_transactions_amount_nonnegative') THEN ALTER TABLE public.gateway_transactions ADD CONSTRAINT gateway_transactions_amount_nonnegative CHECK (amount >= 0); END IF; IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='gateway_transactions_currency_iso3') THEN ALTER TABLE public.gateway_transactions ADD CONSTRAINT gateway_transactions_currency_iso3 CHECK (currency ~ '^[A-Z]{3}$'); END IF; IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='checkout_sessions_currency_iso3') THEN ALTER TABLE public.checkout_sessions ADD CONSTRAINT checkout_sessions_currency_iso3 CHECK (currency ~ '^[A-Z]{3}$'); END IF; IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='checkout_sessions_amount_nonnegative') THEN ALTER TABLE public.checkout_sessions ADD CONSTRAINT checkout_sessions_amount_nonnegative CHECK (amount >= 0); END IF; END $$;